<?php
require '../_guard.php';
$connection = db(); $search = trim($_GET['q'] ?? ''); $message = $_GET['message'] ?? '';
$statement = $connection->prepare('SELECT * FROM amenities ' . ($search !== '' ? 'WHERE name LIKE ? OR description LIKE ? ' : '') . 'ORDER BY active DESC, id');
if ($search !== '') { $term = '%' . $search . '%'; $statement->execute([$term, $term]); } else $statement->execute();
$amenities = $statement->fetchAll(); $pageTitle = 'Amenities | LFT Admin';
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title><?= e($pageTitle) ?></title><link rel="stylesheet" href="../../assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><main class="admin-app"><?php require "../sidebar.php"; ?><div class="admin-main"><header class="admin-topbar"><div><p class="section-label">LFT DUMAGUETE</p><h1>Amenities</h1><p>Manage the details that make the workspace feel complete.</p></div><?php require '../profile.php'; ?></header><?php if ($message): ?><div class="success-message"><?= e($message) ?></div><?php endif; ?><section class="admin-widget booking-panel"><div class="widget-heading"><div><h2>Amenity catalog</h2><p><?= count($amenities) ?> <?= count($amenities) === 1 ? 'amenity' : 'amenities' ?></p></div><a class="btn btn-green" href="add.php">ADD AMENITY</a></div><form class="booking-filters" method="get"><label for="amenity-search">Search</label><input id="amenity-search" name="q" value="<?= e($search) ?>" placeholder="Name or description"><button class="btn btn-green" type="submit">SEARCH</button><?php if ($search !== ''): ?><a class="text-link" href="index.php">Clear</a><?php endif; ?></form><div class="booking-table"><div class="amenity-table-head"><span>Amenity</span><span>Description</span><span>Visibility</span><span>Actions</span></div><?php if (!$amenities): ?><div class="empty-state">No amenities found.</div><?php else: foreach ($amenities as $amenity): ?><div class="amenity-table-row"><div><i class="<?= e($amenity['icon']) ?>"></i><strong><?= e($amenity['name']) ?></strong><small><?= e($amenity['icon']) ?></small></div><span><?= e($amenity['description']) ?></span><span class="table-status <?= $amenity['active'] ? '' : 'status-cancelled' ?>"><?= $amenity['active'] ? 'Published' : 'Hidden' ?></span><div class="row-actions"><a class="text-link" href="edit.php?id=<?= (int) $amenity['id'] ?>">Edit</a><form method="post" action="delete.php" onsubmit="return confirm('Delete this amenity?');"><input type="hidden" name="id" value="<?= (int) $amenity['id'] ?>"><button class="danger-link" type="submit">Delete</button></form></div></div><?php endforeach; endif; ?></div></section></div></main></body></html>
